const projectStores={"alpina": [["Google Play", "https://play.google.com/store/apps/details?id=com.plus.alpina"], ["App Store", "https://apps.apple.com/ru/app/%D0%B0%D0%BB%D1%8C%D0%BF%D0%B8%D0%BD%D0%B0-%D0%BF%D0%BB%D1%8E%D1%81-%D0%B1%D0%B8%D0%B1%D0%BB%D0%B8%D0%BE%D1%82%D0%B5%D0%BA%D0%B0-%D1%83%D1%81%D0%BF%D0%B5%D1%85%D0%B0/id6504778571"]], "gpt": [["Google Play", "https://play.google.com/store/apps/details?id=com.alpina.ai"], ["App Store", "https://apps.apple.com/ru/app/%D0%B0%D0%BB%D1%8C%D0%BF%D0%B8%D0%BD%D0%B0gpt/id6744869588"]]};
const engineeringCases={"migration": {"project": "Alpina Plus", "ru": {"title": "Миграция архитектуры за два месяца", "summary": "Перенос существующего приложения на BLoC: тесты старого поведения, разделение слоёв и работа с ограничениями кодовой базы.", "sections": [["Задача", ["Перевести существующее приложение на BLoC, сохранив работающие пользовательские сценарии."]], ["Сложность", ["Бизнес-логика и сетевые запросы находились непосредственно в экранах. Часть разделов тесно зависела от существующей реализации на Nylo, а крупные модели использовались во многих местах приложения."]], ["Что сделала", ["Перед переписыванием логики покрыла существующий функционал тестами, чтобы проверять сохранение поведения.", "Переносила бизнес-логику из UI, разделяла управление состоянием, репозитории и сетевой слой. Декомпозировала экраны на небольшие виджеты.", "Использовала ListView.builder для ленивого построения элементов списков. Ограничивала обновления нужными частями интерфейса через BlocBuilder и BlocSelector, применяла const там, где это было уместно. Производительность проверяла через Flutter DevTools."]], ["Компромисс", ["Полную замену двух широко используемых моделей отложили, чтобы уложиться в срок миграции. Я разделила их код на меньшие файлы, сохранив существующее поведение."]], ["Результат", ["Миграция завершилась за два месяца. Код стало проще читать и поддерживать, а тесты помогали проверять сохранение старых сценариев."]]]}, "en": {"title": "A two-month architecture migration", "summary": "Moving an existing app to BLoC: tests for existing behaviour, layer separation, and working within codebase constraints.", "sections": [["Task", ["Move an existing app to BLoC while preserving working user journeys."]], ["Challenge", ["Business logic and network requests lived directly in screens. Some sections were tightly coupled to the existing Nylo implementation, and large models were used throughout the app."]], ["What I did", ["Covered existing functionality with tests before rewriting its logic to check behaviour preservation.", "Moved business logic out of the UI and separated state management, repositories, and networking. Broke screens into smaller widgets.", "Used ListView.builder for lazy list construction. Limited updates to the necessary parts of the interface with BlocBuilder and BlocSelector, and used const where appropriate. Checked performance with Flutter DevTools."]], ["Trade-off", ["Replacing two widely used models completely was postponed to meet the migration deadline. I split their code into smaller files while preserving existing behaviour."]], ["Outcome", ["The migration was completed in two months. The code became easier to read and maintain, while tests helped check existing scenarios."]]]}}, "progress": {"project": "Alpina Plus", "ru": {"title": "Прочитанная книга оставалась непрочитанной", "summary": "Нашла ошибку обработки прогресса и исправила отображение завершённых материалов.", "sections": [["Проблема", ["Пользователь доходил до последней страницы EPUB-книги, но после выхода она продолжала отображаться непрочитанной. Ошибка проявлялась для части материалов, включая новые для пользователя и давно добавленные. Аналогичная проблема затрагивала аудио и видео."]], ["Как нашла причину", ["Через логирование проследила получение и передачу параметра progress. Обнаружила ошибку в обработке ответа backend и передаче существующего прогресса."]], ["Что исправила", ["Исправила обработку и передачу данных о прогрессе. Проверила затронутые сценарии вручную и по логам."]], ["Результат", ["Исправила ошибку за один день. В затронутых сценариях завершённый материал стал корректно отображаться как пройденный."]]]}, "en": {"title": "A finished book still appeared unread", "summary": "Found a progress handling bug and fixed the display of completed materials.", "sections": [["Problem", ["A user reached the last page of an EPUB book, but it still appeared unread after leaving. The issue affected some materials, including both newly opened and previously added content. Audio and video had a similar problem."]], ["Finding the cause", ["Used logging to trace reception and forwarding of the progress parameter. Found an error in backend response processing and passing the existing progress value."]], ["Fix", ["Corrected the handling and transfer of progress data. Checked the affected scenarios manually and through logs."]], ["Outcome", ["Fixed the bug in one day. In the affected scenarios, completed material was correctly shown as finished."]]]}}, "streaming": {"project": "AlpinaGPT", "ru": {"title": "Посимвольный AI-ответ в реальном времени", "summary": "Буферизация SSE-данных, последовательная анимация текста и восстановление истории после возвращения в чат.", "sections": [["Задача", ["Показывать ответ AI посимвольно во время генерации, не дожидаясь получения полного текста."]], ["Сложность", ["Части ответа поступали через SSE с переменной скоростью. Требовалось согласовать поступление данных с анимацией текста и корректно обработать уход пользователя с экрана."]], ["Что сделала", ["Реализовала буфер на основе Queue<String>. Поступающие части текста разбивались на символы и помещались в очередь. Timer.periodic последовательно извлекал символы и обновлял отображаемый ответ.", "Если текст поступал быстрее анимации, он накапливался в очереди и выводился последовательно.", "При уходе с экрана SSE-соединение закрывалось. После возвращения приложение запрашивало историю у backend и восстанавливало сообщения в состоянии BLoC."]], ["Проверка", ["Автоматизированный тест проверял переходы состояний загрузки, получения частей ответа и успешного завершения, а также накопление текста."]], ["Результат", ["Пользователь видел ответ по мере генерации. После возвращения в чат восстанавливалась доступная история без необходимости повторно отправлять сообщение."]]]}, "en": {"title": "Character-by-character AI responses in real time", "summary": "SSE buffering, sequential text animation, and history restoration when returning to the chat.", "sections": [["Task", ["Display AI responses character by character during generation without waiting for the complete text."]], ["Challenge", ["Response chunks arrived through SSE at variable speeds. Data reception had to be coordinated with the text animation, including handling the user leaving the screen."]], ["What I did", ["Built a buffer using Queue<String>. Incoming text chunks were split into characters and queued. Timer.periodic extracted characters sequentially and updated the displayed response.", "When text arrived faster than the animation, it accumulated in the queue and was displayed in order.", "The SSE connection was closed on leaving the screen. On return, the app requested history from the backend and restored messages in BLoC state."]], ["Verification", ["An automated test checked transitions through loading, response chunk reception, and successful completion, as well as text accumulation."]], ["Outcome", ["Users saw the response as it was generated. On returning to the chat, available history was restored without requiring the message to be sent again."]]]}}};
