  document.querySelectorAll('.project-image img').forEach(img=>{img.alt=(next==='ru'?'Экран приложения ':'App screenshot: ')+img.closest('article').querySelector('h3').textContent});

  document.getElementById('menu').setAttribute('aria-label',next==='ru'?'Открыть меню':'Open menu');
  updateThemeLabel();if(activeProject)renderProject(activeProject);if(activeCase)renderEngineeringCase(activeCase);
  try{localStorage.setItem('lika-language',next)}catch{}
