const menu=document.getElementById('menu'),nav=document.querySelector('.header nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰'});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
document.querySelectorAll('.engineering-card').forEach((card,index)=>card.style.setProperty('--case-delay',`${index*110}ms`));
if('IntersectionObserver' in window){document.documentElement.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const achievementPlayed=new WeakSet(),achievementFrames=new Map();
function revealAchievement(element){
  if(achievementPlayed.has(element))return;
  achievementPlayed.add(element);
  const number=element.querySelector('.achievement-number'),target=Number(element.dataset.count);
  if(reduced.matches){number.textContent=String(target);return}
  number.animate([{opacity:0,transform:'translateY(16px) scale(.85)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:750,easing:'cubic-bezier(.16,1,.3,1)'});
  const start=performance.now();
  const tick=now=>{const progress=Math.min(1,(now-start)/1000);number.textContent=String(Math.round(target*(1-Math.pow(1-progress,3))));if(progress<1&&!reduced.matches)achievementFrames.set(element,requestAnimationFrame(tick));else{number.textContent=String(target);achievementFrames.delete(element)}};
  achievementFrames.set(element,requestAnimationFrame(tick));
}
const achievementObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){revealAchievement(entry.target);achievementObserver.unobserve(entry.target)}}),{threshold:.6}):null;
function prepareAchievements(){
  document.querySelectorAll('.achievement-card strong[data-count]').forEach(element=>{
    cancelAnimationFrame(achievementFrames.get(element));achievementFrames.delete(element);
    const text=element.textContent,match=text.match(/^(\d+)(.*)$/);if(!match)return;
    const readable=document.createElement('span'),number=document.createElement('span'),suffix=document.createElement('span');
    readable.className='achievement-readable';readable.textContent=text;
    number.className='achievement-number';number.textContent=match[1];suffix.textContent=match[2];number.setAttribute('aria-hidden','true');suffix.setAttribute('aria-hidden','true');
    element.replaceChildren(readable,number,suffix);
    if(achievementPlayed.has(element))return;
    if(achievementObserver)achievementObserver.observe(element);else revealAchievement(element);
  });
}
prepareAchievements();document.addEventListener('portfolio:languagechange',prepareAchievements);
